protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: now throws for Cosmos DB entities.
    // Manage indexing via Azure Portal, Bicep, or Terraform instead.

    modelBuilder.Entity<Product>(b =>
    {
        b.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents and direct SQL queries
        // (e.g. WHERE c.Discriminator = 'Product') remain compatible.
        b.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed id format from "Product|123" to "123".
        // Preserve the old compound format so FindAsync/point-reads work
        // against existing documents.
        b.HasRootDiscriminatorInJsonId(true);
    });
}

